import  {useEffect } from 'react';
import ReactDOM from 'react-dom/client';
import './index.css';
import App from './App';
import reportWebVitals from './reportWebVitals';
import { init, getClient } from "@sentry/react";
import { NotificationProvider } from './contexts/NotificationContext';
import { DataProvider } from './contexts/DataContext';
import { ModalProvider } from './contexts/ModalProvider';
import { SettingsProvider } from './contexts/SettingsProvider';
import { LockdownProvider } from './contexts/LockdownContext';
import { DebugProvider } from './contexts/DebugContext';
import { EmployeeAuthProvider } from './contexts/EmployeeAuthContext';
import { useNotification } from './contexts/NotificationContext';
import * as Sentry from "@sentry/react";
import ErrorBoundary from './components/ErrorBoundary';
import { SiteConfigProvider } from './contexts/SiteConfigContext';
import { logClientError } from './utils/activityLog';
import { startPriceSync } from './utils/pricing';
import { startFormRulesSync } from './utils/formRules';
import { startCustomRolesSync } from './utils/customRoles';
import ExportProgressModal from './components/ExportProgressModal';
import { isChunkLoadError, reloadOnceForNewVersion } from './utils/chunkReload';

// --- START: Fallback Error Reporting ---
const discordErrorWebhookQueue = [];
let isProcessingDiscordQueue = false;
let isSentryBlocked = false; // Flag to track if Sentry connectivity failed

/**
 * Processes the queue of Discord error messages one by one with a delay.
 * This acts as a rate-limiter to prevent spamming the webhook.
 */
const processDiscordErrorQueue = async () => {
    if (isProcessingDiscordQueue || discordErrorWebhookQueue.length === 0) return;

    const webhookURL = null;
    if (!webhookURL) {
        // Webhooks Discord retirés : on vide silencieusement la file (plus de bruit console). La trace des
        // erreurs passe par le journal d'activité (logClientError) et par Sentry.
        discordErrorWebhookQueue.length = 0;
        return;
    }

    isProcessingDiscordQueue = true;
    const payload = discordErrorWebhookQueue.shift();
    try {
        await fetch(webhookURL, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });
    } catch (e) {
        console.error("CRITICAL: Failed to send Discord error webhook.", e);
    } finally {
        // Rate limit: wait 2 seconds before processing the next item.
        setTimeout(() => {
            isProcessingDiscordQueue = false;
            processDiscordErrorQueue(); // Process next item
        }, 2000);
    }
};

/**
 * Creates and queues a Discord embed for an unhandled error.
 * @param {object} errorDetails - Details about the caught error.
 */
export const sendDiscordErrorWebhook = (errorDetails) => {
    // Journal d'activité (panneau admin) : la trace principale des erreurs vues par les utilisateurs connectés.
    logClientError(errorDetails);

    // Try to get the Sentry event ID if available
    let sentryEventId = null;
    if (window.Sentry && window.Sentry.lastEventId) {
        sentryEventId = window.Sentry.lastEventId();
    } else if (Sentry && Sentry.lastEventId) {
        sentryEventId = Sentry.lastEventId();
    }

    const embed = {
        
        title: errorDetails.isButtonClickError ? "🚨 Erreur de clic sur le bouton 🚨" : "🚨 Erreur d'application non gérée 🚨",
        description: "Une erreur non gérée a été interceptée par le gestionnaire global d'erreurs.",
        color: isSentryBlocked ? 0xFFA500 : 0xDE354C, // Orange if Sentry is blocked, Red otherwise
        fields: [
            { name: "Type d'erreur", value: errorDetails.isButtonClickError ? "Interaction UI Bouton" : "énéral", inline: true },
            { name: "Statut Sentry", value: isSentryBlocked ? "⚠️ Bloqué / Inaccessible" : "✅ Actif", inline: true },
            { name: "Message d'erreur", value: `\`${String(errorDetails.message).substring(0, 1000)}\``, inline: false },
            { name: "Fichier source", value: errorDetails.source || "N/A", inline: true },
            { name: "Ligne", value: errorDetails.lineno || "N/A", inline: true },
            { name: "Colonne", value: errorDetails.colno || "N/A", inline: true },
            { name: "Agent utilisateur", value: `\`${navigator.userAgent}\``, inline: false },
            { name: "Trace de la pile", value: `\`${String(errorDetails.stack).substring(0, 1000)}\``, inline: false },
            sentryEventId ? { name: "Sentry Trace/Event ID", value: `\`${sentryEventId}\``, inline: false } : null,
        ].filter(Boolean),
        timestamp: new Date().toISOString(),
        footer: { text: "PHMC-FR Tools - Gestionnaire global des erreurs" }
    };
    discordErrorWebhookQueue.push({ content: '<@1461861710955548693>', embeds: [embed] });
    processDiscordErrorQueue(); // Start processing the queue if it's not already running
};

init({
  dsn: "https://965cbe7aac6ced00a3097177c2be471f@o4510345492234240.ingest.de.sentry.io/4510345505407056",
  sendDefaultPii: true,
  integrations: [
    Sentry.browserTracingIntegration(),
    Sentry.replayIntegration({
      maskAllText: false,
      blockAllMedia: false,
    }),
  ],
  // Avertissement inoffensif du navigateur (un ResizeObserver qui redimensionne ce qu'il observe) : ni erreur, ni bruit dans Sentry.
  ignoreErrors: [/ResizeObserver loop (limit exceeded|completed with undelivered notifications)/],
  tracesSampleRate: 1.0,
  replaysSessionSampleRate: 0.1,
  replaysOnErrorSampleRate: 1.0,
  tracePropagationTargets: ["localhost", "https://phmc-tools.com/", "https://1luckyle.github.io/", /^\//],
});
console.log("Sentry has been initialized.");
window.Sentry = Sentry;
console.log("Sentry has been initialized and exposed on window.Sentry");

// Chargement d'un fichier d'une ancienne version (import dynamique hors d'un composant paresseux) : on recharge la page.
window.addEventListener('unhandledrejection', (event) => {
    if (isChunkLoadError(event.reason)) reloadOnceForNewVersion();
});

// --- Global Error Handling Setup ---
window.onerror = (message, source, lineno, colno, errorObject) => {
    // Ignore common, non-critical errors that can create a lot of noise.
    if (typeof message === 'string' && /ResizeObserver loop (limit exceeded|completed with undelivered notifications)/.test(message)) {
        return true; // Suppress this error from being processed further.
    }

    // --- Button Error Detection ---
    let isButtonClickError = false;
    if (errorObject && typeof errorObject.stack === 'string') {
        // Check for common patterns of event handlers in stack traces
        if (errorObject.stack.includes('onClick') || errorObject.stack.includes('handleClick')) {
            isButtonClickError = true;
        }
    }
    // --- End Button Error Detection ---

    // Queue the error for reporting to Discord.
    const errorDetails = {
        message,
        source,
        lineno,
        colno,
        error: errorObject,
        stack: errorObject ? errorObject.stack : 'N/A',
        isButtonClickError // Pass the flag to the webhook function
    };
    sendDiscordErrorWebhook(errorDetails);

    // Return false to ensure the error is still processed by other handlers (like Sentry's)
    // and the default browser console output.
    return false;
};

const Root = () => {
    const { showNotification, removeNotification } = useNotification();

    useEffect(() => {
        const checkSentryConnectivity = async () => {
            // Wait a moment for Sentry's client to be fully available after init.
            await new Promise(resolve => setTimeout(resolve, 100));
            
            const client = getClient();

            if (!client || !client.getDsn()) {
                console.error("Sentry client or DSN not found. Sentry reporting will fail.");
                isSentryBlocked = true; // Set the flag
                return;
            }

            const dsn = client.getDsn();
            const ingestUrl = `${dsn.protocol}://${dsn.host}/api/${dsn.projectId}/envelope/`;

            try {
                // We use 'no-cors' because we don't need the response, just to see if the request can be made.
                // A successful request (even if opaque) suggests no network-level blocking (e.g., ad-blockers).
                await fetch(ingestUrl, { method: 'HEAD', mode: 'no-cors' });
                console.log("Sentry connectivity check successful. Discord reports will show Sentry as 'Active'.");
                isSentryBlocked = false;
            } catch (error) {
                console.warn("Sentry connectivity check failed. Sentry may be blocked. Discord reports will reflect this. Notification dispatched to User", error);
                isSentryBlocked = true; // Set the flag

                const adblockNotificationId = showNotification(
                    'Il semble que vous ayez un bloqueur de publicités activé. Nous comprenons votre choix, mais les bloqueurs de publicités peuvent parfois perturber le fonctionnement de ce site, notamment nos outils de suivi des erreurs. Pour nous aider à corriger les bugs et à améliorer le site, merci de désactiver votre bloqueur de publicités pour ce domaine. Nous vous remercions de votre collaboration !',
                    'exclamation-triangle',
                    0, // Set duration to 0 for persistence
                    [{
                        label: 'Fermer',
                        handler: () => removeNotification(adblockNotificationId)
                    }]
                );
            }
        };

        checkSentryConnectivity();
    }, []);

    return (
        <>
            <App />
            <ExportProgressModal />
        </>
    );
};

startFormRulesSync(); // champs obligatoires des formulaires (Admin → Champs obligatoires)
startPriceSync(); // tarifs des formulaires (Boîte à outils → Comptabilité → Tarifs des formulaires)
startCustomRolesSync(); // rôles du personnel créés dans l'interface (ajout d'un poste de recrutement) : ajoutés aux rôles d'origine
const container = document.getElementById('root');
const root = ReactDOM.createRoot(container);
root.render(
      <ErrorBoundary>
        <NotificationProvider>
          <DataProvider>
            <ModalProvider>
              <SettingsProvider>
                <LockdownProvider>
                  <SiteConfigProvider>
                    <DebugProvider>
                      <EmployeeAuthProvider>
                        <Root />
                      </EmployeeAuthProvider>
                    </DebugProvider>
                  </SiteConfigProvider>
                </LockdownProvider>
              </SettingsProvider>
            </ModalProvider>
          </DataProvider>
        </NotificationProvider>
      </ErrorBoundary>
);

// If you want to start measuring performance in your app, pass a function
// to log results (for example: reportWebVitals(console.log))
// or send to an analytics endpoint. Learn more: https://bit.ly/CRA-vitals
reportWebVitals();